  async function teamDrainToolCalls(task,response,ctx){let hops=0;while(response?.ok&&response.payload?.request?.calls?.length&&hops<8){const calls=[];for(const call of response.payload.request.calls.slice(0,8)){const tool=String(call?.tool||"");if(!tool)continue;calls.push({tool,result:await B.executeTool?.(tool,call?.args||{})})}response=await sendProviderTask(task,"",ctx,[],{calls},response.requestId||task.requestId||"");hops++}return response}
  async function osminogTeamAsk(threadId,message,options={}){
    await loadThreads();
    const thread=threads.find(t=>t.id===threadId);if(!thread)throw new Error("Агент не найден");
    const provider=thread.provider||"gpt";
    if(provider==="gpt"){if(!connected)await connect();if(!connected)throw new Error("ChatGPT не подключён")}else if(!await providerAvailable(provider))throw new Error(`${providerLabel(provider)} не подключён`);
    const pins=options.fullProject?[]:await pinsForThread(thread.id),ctx=contextForPrompt(message,thread,pins);
    if(options.fullProject){ctx.chat.kind="team";ctx.chat.instruction="OSMINOG Team Room: use the whole project, commands and verified patches. Add a new contribution; never repeat another agent.";ctx.projectMap=B.getProjectMap?.({limit:520})||ctx.projectMap;ctx.objects=(B.listCanvasObjects?.({limit:320,include_preview:true})||{}).objects||ctx.objects;ctx.capabilities.projectControl={access:"owner",actions:["set","create","delete","connect","disconnect"],tools:["canvas_status","list_canvas_objects","get_project_map","get_selection","get_viewport","get_object","get_connections","search_canvas","get_recent_changes","read_object_text","read_code","read_browser_dom","capture_selection_image","capture_object_image","capture_viewport_image","capture_canvas_overview_image","browser_tabs","browser_open","browser_close","markdown_list","markdown_read","markdown_write","agent_list","agent_message","provider_list","provider_open","media_crew","project_folder_status","project_folder_list","project_folder_read","project_folder_write","github_status","github_list_tree","github_search_code","github_fetch_file","github_compare","github_create_branch","github_commit_files","github_open_pr","github_workflow_runs","github_dispatch_workflow","module_status","github_status","github_list_tree","github_search_code","github_fetch_file","github_create_branch","github_commit_files","github_open_pr","github_dispatch_workflow","github_get_workflow_runs"]}}
    const attachments=Array.isArray(options.attachments)?options.attachments:[],images=attachments.filter(a=>a?.kind==="image"||a?.kind==="pdf").map(a=>({name:a.name,type:a.type,size:a.size,dataUrl:a.dataUrl||a.previewDataUrl})),mediaCrew=globalThis.OSMINOGProviderRegistry?.selected?.()||[];
    ctx.capabilities.media={attachments:attachments.map(a=>({kind:a.kind,name:a.name,type:a.type,size:a.size||0})),crew:mediaCrew.map(p=>({id:p.id,name:p.name,category:p.category,caps:p.caps})),tools:["provider_list","provider_open","media_crew","project_folder_status","project_folder_list","project_folder_read","project_folder_write","github_status","github_list_tree","github_search_code","github_fetch_file","github_compare","github_create_branch","github_commit_files","github_open_pr","github_workflow_runs","github_dispatch_workflow"]};
    if(options.execute)ctx.execution={required:true,protocol:"osminog.patch/v1",mustUseExistingIds:true,spatialReferents:"Resolve top/bottom/left/right from actual object bounds in projectMap. Never invent an ID."};
    const task={threadId:thread.id,thread:{...thread},provider,pins,text:message,ctx,edit:!!options.execute,retry:0,requestId:"",attachments};
    const prefix=`[OSMINOG TEAM ROOM]\nMission mode: ${options.mode||"council"}.\nYou are ${thread.name}, ${ROLE_LABELS[thread.role||"universal"]}. You have owner project access through tools and osminog.patch/v1. Contribute something NEW; do not greet, echo, paraphrase or repeat earlier messages. ${options.execute?"EXECUTION IS REQUIRED: resolve the real target from projectMap/selection and return a real validated osminog.patch/v1. Spatial words such as topmost/bottom/left/right refer to actual bounds. If a shape must become a true circle, use shapeKind=ellipse and make width and height equal while preserving its center. Do not claim completion without a patch.":"Discuss concretely and leave execution to the final executor."}\n\n`;
    let response=await sendProviderTask(task,prefix+message+textAttachmentBlock(attachments),ctx,images);
    response=await teamDrainToolCalls(task,response,ctx);
    if(options.execute&&response?.ok&&!response.payload?.patch?.actions?.length){
      for(let attempt=1;attempt<=2&&!response.payload?.patch?.actions?.length;attempt++){
        const correction=`[OSMINOG TEAM EXECUTION RETRY ${attempt}/2]\nThe previous answer did not contain a usable osminog.patch/v1, so the task is NOT complete.\nOriginal owner mission: ${message}\nUse only IDs present in projectMap/objects/selection. Resolve spatial references from bounds (smallest y = uppermost; largest y = lower; smallest x = left; largest x = right) among relevant visible objects. If you need more detail, request tools first. Then return exactly one valid osminog.patch/v1 JSON machine block with concrete set/create/delete/connect/disconnect actions. For a requested true circle use shapeKind=ellipse and equal w/h while preserving the target center. Do not answer with promises or prose-only completion.`;
        response=await sendProviderTask(task,correction,ctx,attempt===1?images:[]);
        response=await teamDrainToolCalls(task,response,ctx);
      }
    }
    if(!response?.ok)throw new Error(response?.error||`${providerLabel(provider)} не ответил`);
    const payload=response.payload||{},text=cleanMachineControl(payload.text),media=responseMedia(payload,text);
    return{ok:true,thread:{id:thread.id,name:thread.name,provider,role:thread.role||"universal",color:providerColor(provider)},text,media,patch:payload.patch||null,request:payload.request||null,requestId:payload.requestId||response.requestId||""}
  }
  async function osminogTeamApplyPatch(patch,options={}){if(!patch?.actions?.length)throw new Error("Агент не вернул patch");const staged=await B.executeTool?.("propose_canvas_patch",patch);if(staged?.error)throw new Error(staged.error);if(options.autoApply!==false)B.applyPatch?.();return{ok:true,staged,applied:options.autoApply!==false}}
