  async function apiCreateAgent(args={}){const previous=activeThreadId,t=await createThread(String(args.provider||activeThread()?.provider||"gpt"));t.name=String(args.name||t.name).trim().slice(0,40)||t.name;t.role=ROLE_LABELS[String(args.role||"")]?String(args.role):["universal","layout","copy","research","design","code"].includes(String(args.role))?String(args.role):"universal";t.permission="owner";t.capabilities=["read","create","set","delete","connect","browser","code","files","commands"];await chrome.storage.local.set({[THREADS_KEY()]:threadStore()});if(args.activate===false&&previous!==t.id)await switchThread(previous);renderThreadTabs();return{ok:true,agent:{id:t.id,name:t.name,provider:t.provider,role:t.role,permission:t.permission}}}
