  async function apiRemoveAgent(args={}){const id=String(args.id||args.agentId||"");if(!id||id==="main")return{error:"The main agent cannot be removed"};const t=threads.find(x=>x.id===id);if(!t)return{error:"Agent does not exist"};if(!confirm(`OSMINOG просит удалить агента «${t.name}».\n\nРазрешить?`))return{error:"Agent removal cancelled by owner"};try{await chrome.storage.local.remove([threadChatKey(id),threadContextKey(id)])}catch{}threads=threads.filter(x=>x.id!==id);if(activeThreadId===id){activeThreadId="main";await loadChat()}await chrome.storage.local.set({[THREADS_KEY()]:threadStore()});renderThreadTabs();return{ok:true,removed:id}}
