  // The main chat owns the autonomous Poseidon executor. Agent chats keep the
  // parallel task runner, but the permanent main thread must never be routed
  // through that one-response path. Use a capture listener so this remains the
  // single submit route even while the legacy bubble listener is kept for
  // backwards compatibility with older saved editor documents.
  q("#gptPresenceForm")?.addEventListener("submit",async event=>{
    event.preventDefault();
    event.stopImmediatePropagation();
    const input=q("#gptPresenceInput"),text=String(input?.value||"").trim();
    if(!text&&!pendingAttachments.length)return;
    const visible=pendingAttachments.slice();
    pendingAttachments=[];
    renderAttachmentTray();
    if(input)input.value="";
    autoSizeComposer();
    if(document.body.classList.contains("mode-team")&&activeThreadId==="main"){
      try{
        const api=globalThis.OSMINOGTeamAPI;
        if(!api?.run)throw new Error("Командный движок ещё не готов");
        await api.run(text||"Проанализируйте прикреплённые материалы и выполните следующий шаг.",{attachments:visible,unified:true});
      }catch(error){
        add("assistant",error?.message||String(error),[],{author:"OSMINOG",color:"#ef4444",source:"team"});
      }
      return;
    }
    add("user",text,visible);
    scrollChatBottom(true);
    // sendPrompt consumes pendingAttachments itself. Restore this request's
    // captured attachments immediately before selecting the execution route.
    pendingAttachments=visible;
    if(activeThreadId==="main")sendPrompt(text||"Посмотри прикреплённый материал и выполни требуемое действие.");
    else sendPromptParallel(text||"Посмотри прикреплённый материал и выполни требуемое действие.");
  },true);

  document.dispatchEvent(new CustomEvent("osminog:agents-ready"));

